"""Dashboard query validation, filesystem reads, and JSON-oriented payloads."""

from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from urllib.parse import quote, urlencode

from . import quest_fs
from .dashboard_runs import ActiveRunTracker
from .quest_lock import QuestLock
from .quest_types import IssueEntry, IssueResponseEntry, QuestMeta, QuestState, slice_index_from_dirname
from .worktrees import quest_worktree_path, validate_project_name
_PAUSED_UNTIL_LINE_RE = re.compile(
    r"^\s*Paused\s+until\s+(.+?)\s*$",
    re.IGNORECASE | re.MULTILINE,
)


class DashboardBadRequest(Exception):
    def __init__(self, message: str, *, fields: dict | None = None) -> None:
        self.message = message
        self.fields = fields or {}
        super().__init__(message)


class DashboardNotFound(Exception):
    def __init__(self, message: str) -> None:
        self.message = message
        super().__init__(message)


def quote_query_param(value: str) -> str:
    return quote(value, safe="")


def canonical_quest_dashboard_url(
    *,
    base_url: str,
    project: str,
    quest_type: str,
    quest_number: int,
) -> str:
    q = urlencode(
        {
            "project": project,
            "quest_type": quest_type,
            "quest_number": str(quest_number),
        }
    )
    return f"{base_url.rstrip('/')}/dashboard?{q}"


def parse_project(
    raw: str | None,
    *,
    source_repo_root: Path | None = None,
) -> str:
    if raw is None or not str(raw).strip():
        raise DashboardBadRequest(
            "Missing required query parameter: project",
            fields={"project": "required"},
        )
    project = str(raw).strip()
    try:
        validate_project_name(project)
    except ValueError as e:
        raise DashboardBadRequest(str(e), fields={"project": "invalid"}) from e
    if source_repo_root is not None:
        project_dir = source_repo_root / "projects" / project
        if not project_dir.is_dir():
            raise DashboardNotFound(f"Project not found: {project!r}")
    return project


def parse_max_steps(raw: object | None, *, default: int = 500) -> int:
    if raw is None:
        return default
    if not isinstance(raw, int) or raw < 1:
        raise DashboardBadRequest(
            "max_steps must be a positive integer",
            fields={"max_steps": "invalid"},
        )
    return raw


def parse_experiment_id(raw: str | None) -> str | None:
    if raw is None or not str(raw).strip():
        return None
    return str(raw).strip()


def lock_key_for_checkout(
    source_repo_root: Path,
    meta: QuestMeta,
    checkout: DashboardCheckout,
) -> str:
    from .quest_service import _build_run_lock_key

    return _build_run_lock_key(
        checkout.checkout_root,
        meta.project,
        meta.quest_type,
        meta.quest_number,
        checkout.experiment_id,
    )


def lock_key_for_quest(
    source_repo_root: Path,
    meta: QuestMeta,
    *,
    experiment_id: str | None = None,
) -> str:
    checkout = resolve_dashboard_checkout(
        source_repo_root,
        meta,
        experiment_id=experiment_id,
    )
    return lock_key_for_checkout(source_repo_root, meta, checkout)


@dataclass
class DashboardCheckout:
    checkout_kind: str
    checkout_path: str
    worktree_missing: bool
    checkout_root: Path
    quest_dir: Path
    quest_dir_rel: str
    experiment_id: str | None = None
    experiment_number: int | None = None
    parent_quest_dir: Path | None = None


def resolve_dashboard_checkout(
    source_repo_root: Path,
    meta: QuestMeta,
    *,
    experiment_id: str | None = None,
) -> DashboardCheckout:
    from .experiments import resolve_quest_scope_checkout

    return resolve_quest_scope_checkout(
        source_repo_root,
        meta,
        experiment_id=experiment_id,
    )


def resolve_quest_checkout_root(source_repo_root: Path, quest_dir: Path) -> Path:
    meta = quest_fs.read_quest_meta(quest_dir)
    return resolve_dashboard_checkout(source_repo_root, meta).checkout_root


def resolve_quest_dirs(
    source_repo_root: Path,
    project: str,
    quest_type: str,
    quest_number: int,
    *,
    experiment_id: str | None = None,
) -> tuple[Path, Path]:
    source_qdir = resolve_quest_dir(
        source_repo_root, project, quest_type, quest_number
    )
    meta = quest_fs.read_quest_meta(source_qdir)
    checkout = resolve_dashboard_checkout(
        source_repo_root,
        meta,
        experiment_id=experiment_id,
    )
    return checkout.checkout_root, checkout.quest_dir


def _project_has_quests(source_repo_root: Path, project: str) -> bool:
    for qt in ("main", "side"):
        if quest_fs.list_quest_dirs(source_repo_root, project, qt):
            return True
    return False


def projects_payload(source_repo_root: Path) -> dict:
    roots = quest_fs.iter_project_quest_roots(source_repo_root)
    projects = [
        {"project": root.project}
        for root in roots
        if _project_has_quests(source_repo_root, root.project)
    ]
    default_project = projects[0]["project"] if projects else None
    return {
        "projects": projects,
        "default_project": default_project,
    }


@dataclass
class PauseUntilState:
    kind: str
    until_iso: str | None = None


def read_paused_until_state(quest_dir: Path) -> PauseUntilState:
    path = quest_dir / "paused_until.md"
    if not path.is_file():
        return PauseUntilState(kind="absent")
    text = path.read_text(encoding="utf-8")
    m = _PAUSED_UNTIL_LINE_RE.search(text)
    if not m:
        return PauseUntilState(kind="invalid")
    raw_ts = m.group(1).strip()
    try:
        normalized = raw_ts.replace("Z", "+00:00")
        dt = datetime.fromisoformat(normalized)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        until = dt.astimezone(timezone.utc)
    except ValueError:
        return PauseUntilState(kind="invalid")
    until_iso = until.strftime("%Y-%m-%dT%H:%M:%SZ")
    now = datetime.now(timezone.utc)
    if until > now:
        return PauseUntilState(kind="active", until_iso=until_iso)
    return PauseUntilState(kind="expired", until_iso=until_iso)


def execution_overlay_status(
    *,
    quest_dir: Path,
    lock_key: str,
    quest_type: str,
    quest_number: int,
    lock: QuestLock,
) -> str:
    if quest_fs.has_human_intervention_request(quest_dir):
        return "human_intervention"
    pause = read_paused_until_state(quest_dir)
    if pause.kind == "invalid":
        return "human_intervention"
    if pause.kind == "active":
        return "paused"
    info = lock.get_lock_info(lock_key)
    if (
        info is not None
        and info.quest_type == quest_type
        and info.quest_number == quest_number
    ):
        return "running"
    return "none"


def paused_until_public(pause: PauseUntilState) -> str | None:
    if pause.kind == "active":
        return pause.until_iso
    return None


def issue_status_counts(issues: list[IssueEntry]) -> dict[str, int]:
    open_n = sum(1 for i in issues if i.status == "open")
    completed_n = sum(1 for i in issues if i.status == "completed")
    return {"open": open_n, "completed": completed_n}


def issues_latest_updated_at(issues: list[IssueEntry]) -> str | None:
    if not issues:
        return None
    return max(i.updated_at for i in issues)


def find_slice_dir(quest_dir: Path, slice_number: int) -> Path | None:
    for p in quest_fs.list_slice_dirs(quest_dir):
        if slice_index_from_dirname(p.name) == slice_number:
            return p
    return None


def resolve_quest_dir(
    source_repo_root: Path,
    project: str,
    quest_type: str,
    quest_number: int,
) -> Path:
    qdir = quest_fs.find_quest_dir(source_repo_root, project, quest_type, quest_number)
    if qdir is None:
        raise DashboardNotFound(
            f"No quest found for project={project!r} type={quest_type!r} "
            f"number={quest_number}"
        )
    return qdir


def parse_quest_type(raw: str | None) -> str:
    if raw is None or not str(raw).strip():
        raise DashboardBadRequest(
            "Missing required query parameter: quest_type",
            fields={"quest_type": "required"},
        )
    if raw not in ("main", "side"):
        raise DashboardBadRequest(
            "quest_type must be 'main' or 'side'",
            fields={"quest_type": "invalid"},
        )
    return raw


def parse_quest_number(raw: str | None) -> int:
    if raw is None or not str(raw).strip():
        raise DashboardBadRequest(
            "Missing required query parameter: quest_number",
            fields={"quest_number": "required"},
        )
    try:
        n = int(raw, 10)
    except ValueError as e:
        raise DashboardBadRequest(
            "quest_number must be an integer",
            fields={"quest_number": "invalid"},
        ) from e
    if n < 0:
        raise DashboardBadRequest(
            "quest_number must be non-negative",
            fields={"quest_number": "invalid"},
        )
    return n


PhysicalPlanResponseEntry = IssueResponseEntry


def read_physicalplan_issue_responses(quest_dir: Path) -> list[IssueResponseEntry]:
    return quest_fs.read_issue_responses(
        quest_dir / "physicalplan_issue_responses.md"
    )


def issue_entry_to_card(entry: IssueEntry) -> dict:
    return {
        "issue_id": entry.issue_id,
        "status": entry.status,
        "owner_role": entry.owner_role,
        "created_at": entry.created_at,
        "updated_at": entry.updated_at,
        "title": entry.title,
        "details": entry.details,
        "resolution_notes": entry.resolution_notes,
    }


def summarize_responses_for_issues(
    issues: list[IssueEntry],
    responses: list[IssueResponseEntry],
) -> list[dict]:
    ids = {i.issue_id for i in issues}
    matched = [r for r in responses if r.issue_id in ids]
    return [
        {
            "issue_id": r.issue_id,
            "response_timestamp": r.response_timestamp,
            "outcome": r.outcome,
            "explanation_preview": r.explanation[:500]
            + ("…" if len(r.explanation) > 500 else ""),
        }
        for r in matched
    ]


def human_intervention_payload(quest_dir: Path) -> dict:
    path = quest_dir / "human_intervention_request.md"
    if not path.is_file():
        return {
            "present": False,
            "markdown": None,
            "path": "human_intervention_request.md",
            "updated_at": None,
        }
    st = path.stat()
    updated = datetime.fromtimestamp(st.st_mtime, tz=timezone.utc).strftime(
        "%Y-%m-%dT%H:%M:%SZ"
    )
    return {
        "present": True,
        "markdown": path.read_text(encoding="utf-8"),
        "path": "human_intervention_request.md",
        "updated_at": updated,
    }


def physicalplan_issues_payload(quest_dir: Path) -> dict:
    path = quest_dir / "physicalplan_issues.md"
    issues = quest_fs.read_issues(path)
    counts = issue_status_counts(issues)
    responses = read_physicalplan_issue_responses(quest_dir)
    latest = issues_latest_updated_at(issues)
    resp_ts = [r.response_timestamp for r in responses]
    latest_response_ts = max(resp_ts) if resp_ts else None
    latest_updates = [x for x in (latest, latest_response_ts) if x]
    latest_overall = max(latest_updates) if latest_updates else None
    return {
        "issues_path": "physicalplan_issues.md",
        "issues": [issue_entry_to_card(i) for i in issues],
        "open_count": counts["open"],
        "completed_count": counts["completed"],
        "latest_issue_updated_at": latest,
        "latest_response_updated_at": latest_response_ts,
        "latest_update_at": latest_overall,
        "responses_summary": summarize_responses_for_issues(issues, responses),
    }


def _experiment_start_step_public(start_step) -> dict:
    payload: dict = {
        "global_step": start_step.global_step,
        "step_commit": start_step.step_commit,
        "base_commit": start_step.base_commit,
    }
    if start_step.role is not None:
        payload["role"] = start_step.role
    if start_step.step_log is not None:
        payload["step_log"] = start_step.step_log
    return payload


def _experiment_stop_condition_public(stop_condition) -> dict:
    return {
        "machine_path": stop_condition.machine_path,
        "node_name": stop_condition.node_name,
    }


def _experiment_can_land(*, worktree_state: str, meta_status: str) -> bool:
    return (
        worktree_state == QuestState.ExperimentComplete.value
        or meta_status == "experiment_complete"
    )


def _summarize_archived_logs(logs_dir: Path) -> list[dict]:
    if not logs_dir.is_dir():
        return []
    summaries: list[dict] = []
    for path in sorted(logs_dir.glob("*.jsonl")):
        try:
            line_count = sum(1 for _ in path.open(encoding="utf-8"))
        except OSError:
            line_count = 0
        summaries.append(
            {
                "filename": path.name,
                "path": f"logs/{path.name}",
                "line_count": line_count,
            }
        )
    return summaries


def _archived_issue_entries(issues_dir: Path) -> list[dict]:
    if not issues_dir.is_dir():
        return []
    entries: list[dict] = []
    for path in sorted(issues_dir.rglob("*.md")):
        rel = path.relative_to(issues_dir).as_posix()
        item: dict = {"path": rel}
        try:
            issues = quest_fs.read_issues(path)
            item["open_count"] = sum(1 for i in issues if i.status == "open")
            item["completed_count"] = sum(
                1 for i in issues if i.status == "completed"
            )
            item["issues"] = [issue_entry_to_card(i) for i in issues]
        except (ValueError, OSError):
            item["parse_error"] = True
        entries.append(item)
    return entries


def _archived_response_entries(responses_dir: Path) -> list[dict]:
    if not responses_dir.is_dir():
        return []
    entries: list[dict] = []
    for path in sorted(responses_dir.rglob("*.md")):
        rel = path.relative_to(responses_dir).as_posix()
        item: dict = {"path": rel}
        try:
            responses = quest_fs.read_issue_responses(path)
            item["response_count"] = len(responses)
            item["responses"] = [
                {
                    "issue_id": r.issue_id,
                    "response_timestamp": r.response_timestamp,
                    "outcome": r.outcome,
                    "explanation_preview": r.explanation[:500]
                    + ("…" if len(r.explanation) > 500 else ""),
                }
                for r in responses
            ]
        except (ValueError, OSError):
            item["parse_error"] = True
        entries.append(item)
    return entries


def _archived_experiment_summary(exp_meta) -> dict:
    summary: dict = {
        "experiment_id": exp_meta.experiment_id,
        "experiment_number": exp_meta.experiment_number,
        "description": exp_meta.description,
        "status": exp_meta.status,
        "start_step": _experiment_start_step_public(exp_meta.start_step),
        "stop_condition": _experiment_stop_condition_public(
            exp_meta.stop_condition
        ),
        "created_at": exp_meta.created_at,
        "landed_at": exp_meta.landed_at,
    }
    if exp_meta.remote_branch is not None:
        summary["remote_branch"] = exp_meta.remote_branch
    return summary


def open_experiment_summary_row(
    *,
    source_repo_root: Path,
    source_qdir: Path,
    meta: QuestMeta,
    exp_meta,
    lock: QuestLock,
) -> dict | None:
    from .experiments import (
        _experiment_worktree_exists,
        experiment_worktree_path,
    )

    if not _experiment_worktree_exists(source_repo_root, exp_meta):
        return None
    checkout_root = experiment_worktree_path(source_repo_root, exp_meta)
    worktree_qdir = quest_fs.find_quest_dir(
        checkout_root,
        meta.project,
        meta.quest_type,
        meta.quest_number,
    )
    if worktree_qdir is None:
        return None
    state_info = quest_fs.read_quest_state(worktree_qdir)
    lock_key = lock_key_for_quest(
        source_repo_root,
        meta,
        experiment_id=exp_meta.experiment_id,
    )
    overlay = execution_overlay_status(
        quest_dir=worktree_qdir,
        lock_key=lock_key,
        quest_type=meta.quest_type,
        quest_number=meta.quest_number,
        lock=lock,
    )
    return {
        "kind": "experiment",
        "experiment_id": exp_meta.experiment_id,
        "experiment_number": exp_meta.experiment_number,
        "project": meta.project,
        "quest_type": meta.quest_type,
        "quest_number": meta.quest_number,
        "quest_slug": meta.quest_slug,
        "description": exp_meta.description,
        "status": exp_meta.status,
        "state": state_info.state.value,
        "start_step": _experiment_start_step_public(exp_meta.start_step),
        "stop_condition": _experiment_stop_condition_public(
            exp_meta.stop_condition
        ),
        "worktree_path": str(checkout_root),
        "branch_name": exp_meta.branch_name,
        "can_land": _experiment_can_land(
            worktree_state=state_info.state.value,
            meta_status=exp_meta.status,
        ),
        "execution_overlay_status": overlay,
        "updated_at": state_info.updated_at,
    }


def open_experiment_summary_rows(
    source_repo_root: Path,
    project: str,
    lock: QuestLock,
) -> list[dict]:
    from .experiments import list_experiment_dirs, read_experiment_meta

    rows: list[dict] = []
    for quest_type in ("main", "side"):
        for qdir in quest_fs.list_quest_dirs(source_repo_root, project, quest_type):
            meta = quest_fs.read_quest_meta(qdir)
            for exp_dir in list_experiment_dirs(qdir):
                meta_path = exp_dir / "experiment.json"
                if not meta_path.is_file():
                    continue
                try:
                    exp_meta = read_experiment_meta(meta_path)
                except (OSError, ValueError):
                    continue
                row = open_experiment_summary_row(
                    source_repo_root=source_repo_root,
                    source_qdir=qdir,
                    meta=meta,
                    exp_meta=exp_meta,
                    lock=lock,
                )
                if row is not None:
                    rows.append(row)
    rows.sort(
        key=lambda r: (
            r["quest_type"],
            r["quest_number"],
            r["experiment_number"],
        ),
        reverse=True,
    )
    return rows


def archived_experiments_payload(
    source_repo_root: Path,
    project: str,
    quest_type: str,
    quest_number: int,
) -> dict:
    from .experiments import experiments_root, list_experiment_dirs, read_experiment_meta

    source_qdir = resolve_quest_dir(
        source_repo_root, project, quest_type, quest_number
    )
    root = experiments_root(source_qdir)
    experiments: list[dict] = []
    if root.is_dir():
        for exp_dir in list_experiment_dirs(source_qdir):
            meta_path = exp_dir / "experiment.json"
            if not meta_path.is_file():
                continue
            try:
                exp_meta = read_experiment_meta(meta_path)
            except (OSError, ValueError):
                continue
            if exp_meta.status != "landed":
                continue
            item = _archived_experiment_summary(exp_meta)
            logs_dir = exp_dir / "logs"
            item["log_count"] = len(_summarize_archived_logs(logs_dir))
            item["issue_file_count"] = len(
                list((exp_dir / "issues").rglob("*.md"))
                if (exp_dir / "issues").is_dir()
                else []
            )
            experiments.append(item)
    experiments.sort(key=lambda e: e["experiment_number"], reverse=True)
    return {
        "project": project,
        "quest_type": quest_type,
        "quest_number": quest_number,
        "experiments": experiments,
    }


def experiment_archive_detail_payload(
    source_repo_root: Path,
    project: str,
    quest_type: str,
    quest_number: int,
    experiment_id: str,
) -> dict:
    from .experiments import (
        ExperimentNotFound,
        find_experiment_by_id,
    )

    source_qdir = resolve_quest_dir(
        source_repo_root, project, quest_type, quest_number
    )
    try:
        exp_meta = find_experiment_by_id(
            source_repo_root,
            project,
            quest_type,
            quest_number,
            experiment_id,
        )
    except ExperimentNotFound as e:
        raise DashboardNotFound(e.message) from e

    exp_dir = source_qdir / "experiments" / f"{exp_meta.experiment_number:04d}"
    payload = _archived_experiment_summary(exp_meta)
    payload.update(
        {
            "project": project,
            "quest_type": quest_type,
            "quest_number": quest_number,
            "quest_slug": exp_meta.quest_slug,
            "branch_name": exp_meta.branch_name,
