    quest_number: int,
    lock: QuestLock,
    run_tracker: ActiveRunTracker,
    experiment_id: str | None = None,
) -> dict:
    meta = quest_fs.read_quest_meta(quest_dir)
    lock_key = lock_key_for_quest(
        source_repo_root,
        meta,
        experiment_id=experiment_id,
    )
    state_info = quest_fs.read_quest_state(quest_dir)
