  return {
    project,
    quest_type: questType,
    quest_number: questNumber,
  };
}

export function BuildLandQuestPayload(project, questType, questNumber) {
  return {
    project,
    quest_type: questType,
    quest_number: questNumber,
  };
}

export function InferQuestDisplayStatus(overview, runStatus) {
  if (!overview) {
    return "idle";
  }
  const overlay =
    overview.execution_overlay_status ??
    runStatus?.execution_overlay_status ??
    "none";
  if (overlay === "human_intervention") {
    return "human_intervention";
  }
  if (overlay === "paused") {
    return "paused";
  }
  if (overlay === "running" || runStatus?.active_run != null) {
    return "running";
  }
  if (overview.quest_state === "Completed") {
    return overview.worktree_missing ? "landed" : "completed";
  }
  return "idle";
}

export function ShouldShowRunButton(overview, runStatus) {
  if (!overview) {
    return false;
  }
  if (overview.quest_state === "Completed") {
    return false;
  }
  if (overview.worktree_missing) {
    return false;
  }
  const overlay =
    overview.execution_overlay_status ??
    runStatus?.execution_overlay_status ??
    "none";
  if (overlay === "human_intervention" || overlay === "paused" || overlay === "running") {
    return false;
  }
  if (runStatus?.active_run != null) {
    return false;
  }
  return true;
}

export function ShouldShowAdvanceButton(overview, runStatus) {
  if (!overview) {
    return false;
  }
  if (overview.quest_state === "Completed") {
    return false;
  }
  if (overview.worktree_missing) {
    return false;
  }
  const overlay =
    overview.execution_overlay_status ??
    runStatus?.execution_overlay_status ??
    "none";
  if (overlay === "paused" || overlay === "running") {
    return false;
  }
  if (runStatus?.active_run != null) {
    return false;
  }
  return true;
}

export function ShouldShowLandButton(overview, runStatus) {
  return InferQuestDisplayStatus(overview, runStatus) === "completed";
}

/**
 * Polls only while getVisible() is true; fires immediately when tab becomes visible again.
 */
export class RefreshScheduler {
  constructor(options) {
    this.m_intervalMs = options.intervalMs;
    this.m_onTick = options.onTick;
    this.m_getVisible = options.getVisible;
    this.m_timer = null;
    this.m_onVisibility = () => {
      if (this.m_getVisible()) {
        void this.m_onTick();
      }
    };
  }

  Start() {
    this.Stop();
    this.m_timer = setInterval(() => {
      if (this.m_getVisible()) {
        void this.m_onTick();
      }
    }, this.m_intervalMs);
    if (typeof document !== "undefined") {
      document.addEventListener("visibilitychange", this.m_onVisibility);
    }
  }

  Stop() {
    if (this.m_timer != null) {
      clearInterval(this.m_timer);
      this.m_timer = null;
    }
    if (typeof document !== "undefined") {
      document.removeEventListener("visibilitychange", this.m_onVisibility);
    }
  }
}

export function MergeRunBadge(overview, runStatus) {
  const status = InferQuestDisplayStatus(overview, runStatus);
  if (status === "human_intervention") {
    return { label: "Human intervention required", variant: "hi" };
  }
  if (status === "paused") {
    const until = overview?.paused_until ?? runStatus?.paused_until;
    return {
      label: until ? `Paused until ${until}` : "Paused",
      variant: "paused",
    };
  }
  if (status === "running") {
    return { label: "Running", variant: "running" };
  }
  if (status === "completed") {
    return { label: "Completed", variant: "completed" };
  }
  if (status === "landed") {
    return { label: "Landed", variant: "landed" };
  }
  return { label: "Idle / Not running", variant: "idle" };
}

