    advanceBtn.addEventListener("click", () => void HandleAdvanceQuestClick());
  }
  const landBtn = main.querySelector("#dash-land-quest");
  if (landBtn) {
    landBtn.addEventListener("click", () => void HandleLandQuestClick());
  }
