    <dl class="dash-kv">
      <dt>Project</dt><dd>${EscapeHtml(ov.project || ov.quest.project || "")}</dd>
      <dt>Key</dt><dd>${EscapeHtml(ov.quest.type + "/" + String(ov.quest.number).padStart(4, "0"))}</dd>
      <dt>Name</dt><dd>${EscapeHtml(ov.quest.name)}</dd>
