        exp.log_count != null
          ? ` · ${EscapeHtml(String(exp.log_count))} log file(s)`
          : "";
      return `<li class="dash-archived-exp">
        <button type="button" class="dash-archived-exp__btn" data-experiment-id="${EscapeHtml(
          exp.experiment_id
        )}">
