  --agui-chat-muted: var(--dash-muted);
  --agui-chat-border: var(--dash-border);
  --agui-chat-accent: var(--dash-accent);
  --agui-chat-live: var(--dash-success);
  --agui-chat-warning: var(--dash-warn);
}

.dash-banner {
  background: var(--dash-warn);
  color: #111;
  padding: 10px 16px;
  font-weight: 600;
}

.dash-banner--error {
  background: var(--dash-danger);
  color: #fff;
}

.dash-banner--success {
  background: var(--dash-success);
  color: #06130a;
}

.dash-topbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--dash-gap);
  padding: 10px 16px;
  border-bottom: 1px solid var(--dash-border);
  background: var(--dash-surface);
}

.dash-topbar label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--dash-muted);
  font-size: 13px;
}

.dash-topbar select {
  min-width: 220px;
  padding: 6px 10px;
  border-radius: 6px;
  border: 1px solid var(--dash-border);
  background: var(--dash-elevated);
  color: var(--dash-text);
}

.dash-btn {
  padding: 6px 14px;
  border-radius: 6px;
  border: 1px solid var(--dash-border);
  background: var(--dash-elevated);
  color: var(--dash-text);
  cursor: pointer;
  font: inherit;
}

.dash-btn:hover {
  border-color: var(--dash-accent);
  color: var(--dash-accent);
}

.dash-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.dash-btn--primary {
  background: var(--dash-accent);
